const op = ($.input.operation || '').toLowerCase();
if (op !== 'list' && op !== 'create') throw new Error('operation must be "list" or "create"');
return { op };

const op = $.steps.routeOperation.output.op;
if (op === 'list') {
  const resp = $.steps.listFiles?.response || {};
  const files = resp.files || [];
  return {
    files: files.map(f => ({ id: f.id, name: f.name, mimeType: f.mimeType, modifiedTime: f.modifiedTime, webViewLink: f.webViewLink })),
    count: files.length,
    nextPageToken: resp.nextPageToken || null,
    summary: `Found ${files.length} file${files.length === 1 ? '' : 's'}`
  };
} else {
  const resp = $.steps.createFile?.response || {};
  const isFolder = (resp.mimeType || '').includes('folder');
  return {
    id: resp.id || '',
    name: resp.name || $.input.name,
    mimeType: resp.mimeType || '',
    webViewLink: resp.webViewLink || '',
    created: !!resp.id,
    summary: resp.id ? `Created ${isFolder ? 'folder' : 'file'} "${resp.name || $.input.name}"` : 'Failed to create'
  };
}
